  "paragraphs": [
   "Cybernetic prosthetics have revolutionized medical technology, offering hope to individuals who have lost limbs. Unlike traditional prosthetics, which are often cumbersome and limited in function, cybernetic versions are designed to integrate {{q1:seamlessly}} with the human nervous system. This integration allows for more natural movement and even sensation. A key development in this field has been the use of myoelectric sensors, which detect electrical signals generated by muscle movements.",
   "One example is a cybernetic hand that can perform delicate tasks such as picking up small objects or typing. This is achieved through advanced algorithms that translate muscle signals into controlled movements. Researchers are also exploring haptic feedback, which would enable users to feel textures and temperatures through their prosthetic limbs. It involves integrating sensors and actuators that mimic the sensation of touch by stimulating the user's nerve endings or skin with electrical signals. This could significantly improve the quality of life for amputees.",
   "[[BOX_1]] The high cost of these prosthetics makes them inaccessible to many. [[BOX_2]] Additionally, the technology requires regular maintenance and updates, which can be a barrier. [[BOX_3]] Current battery life is another limitation, as it restricts the user's ability to wear the prosthetic for extended periods. Researchers are continually working to make these devices more affordable and user-friendly. [[BOX_4]]"
  ],
