  "paragraphs": [
   "Coral reefs are among the most diverse and valuable ecosystems on Earth, providing habitat for countless marine species. However, climate change poses a severe threat to these vibrant underwater communities. Rising sea temperatures lead to coral bleaching, a phenomenon where corals lose their color and essential symbiotic algae, resulting in weakened corals that are more susceptible to disease.",
   "In addition to temperature changes, climate change contributes to ocean acidification through increased atmospheric CO₂ levels. Ocean acidification reduces the availability of calcium carbonate, a crucial component of coral skeletons. [[BOX_1]] As the acidity of seawater increases, corals struggle to maintain their structures, leading to diminished reef growth and stability. [[BOX_2]]",
   "Efforts to {{q3:mitigate}} these impacts include developing coral species that are more resilient to temperature fluctuations and acidification. [[BOX_3]] Scientists are exploring selective breeding and genetic modification as potential solutions. Furthermore, initiatives to reduce CO₂ emissions globally aim to alleviate the stress on coral reefs. [[BOX_4]] The survival of coral reefs depends largely on addressing climate change comprehensively."
  ],
