  "paragraphs": [
   "The Great Smog of London in 1952 was a pivotal event in environmental history. For five days in December, a thick layer of smog blanketed the city, caused by cold weather, windless conditions, and pollutants. The primary sources were coal-burning fires for heating homes and factories, releasing sulfur dioxide and other toxic chemicals.",
   "As the smog settled, it became a health crisis. Visibility was reduced to a few meters, and transportation was disrupted. Many people abandoned their cars, and the ambulance service was severely impacted. Thousands developed respiratory problems, and the death rate surged. The Great Smog caused up to 12,000 {{q2:premature}} deaths and countless illnesses. Hospitals were overwhelmed with patients, and morgues quickly reached capacity.",
   "In response, the British government took action. New regulations aimed at reducing air pollution were established. The most significant was the Clean Air Act of 1956, which restricted coal burning in urban areas and promoted cleaner energy sources. [[BOX_1]]",
   "Despite progress, air pollution remains a global challenge. [[BOX_2]] Many cities still struggle with poor air quality due to industrial activities, vehicle emissions, and other sources. [[BOX_3]] The Great Smog of London serves as a stark reminder of the need to address environmental issues to protect public health. [[BOX_4]]"
  ],
