    "explanation": "<div class=\"expl-line\"><span class=\"expl-label\">定位句</span>Despite high initial costs, building data science offers long-term benefits.</div><div class=\"expl-line\"><span class=\"expl-label\">答案</span>B. It requires special training in data analysis for architects who use it.</div><div class=\"expl-line\"><span class=\"expl-label\">排除</span>A、C、D 在原文中均有对应表述；B 项原文未提及，为应选项。</div>"
