  "paragraphs": [
   "Choreography (the composition and arrangement of dance), once a ceremonial and courtly discipline rooted in ritualistic precision, has undergone a {{q1:profound}} metamorphosis shaped by cultural shifts and artistic redefinition. Initially governed by strict formalism—particularly in classical ballet—it emphasized symmetry, control, and hierarchy. However, the 20th century witnessed a radical departure from these conventions. Visionaries like Martha Graham redefined dance as a medium for emotional expression and psychological depth, challenging ballet's aesthetic rigidity and introducing vocabularies of movement that embraced tension, release, and groundedness, which emphasizes a strong connection to the earth or floor. This evolution marked a transition from spectacle to narrative, with choreography becoming a conduit for storytelling and social commentary.",
   "Today, choreography increasingly reflects a decentralization of artistic authority. [[BOX_1]] Rather than a single choreographer dictating movement, many contemporary works emerge from collaborative processes among dancers, composers, designers, and digital artists. [[BOX_2]] This co-creative model not only democratizes authorship but also fosters performances that are adaptive and responsive—sometimes even improvised or altered in real time. The boundaries between creator and performer blur, yielding works that resist fixed interpretation. [[BOX_3]] In this context, choreography becomes less a finished product and more a living dialogue among disciplines, identities, and ideas. [[BOX_4]]"
  ],
