  "paragraphs": [
   "On June 30, 1908, a massive explosion lit up the sky above the remote forests of Russia's Tunguska region. The blast, believed to be caused by an extraterrestrial object, flattened over 2,000 square kilometers of forest, unleashing energy equivalent to 15 megatons of TNT (a widely used explosive). [[BOX_1]] Initially, this was believed to be caused by a meteorite that struck Earth. [[BOX_2]] However, meteorite impacts leave craters—large bowl-shaped holes. [[BOX_3]] In Tunguska, no crater was found. [[BOX_4]]",
   "The {{q2:prevailing}} explanation is an airburst. As a comet or asteroid enters Earth's atmosphere at tremendous speed, friction between the celestial object and the atmosphere creates large amounts of heat. This heat can cause the comet or asteroid to explode several kilometers above the ground. While {{q3:this theory}} explains the lack of a crater, it raises questions regarding the identity of the celestial object itself: Was it a comet or an asteroid?",
   "Comets are icy, while asteroids are rocky or metallic, and each leaves different chemical clues. Researchers have analyzed soil, vegetation, and tiny particles from the area, but so far the evidence is inconclusive. Continued geochemical studies may one day unveil the identity of the Tunguska explosion's cosmic perpetrator."
  ],
